#include <stdio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>

// Define a signal handler to ensure the thread wakes up if a signal is sent
void handle_signal(int signum) {
    printf("\n[Signal %d received! Interrupting sleep.]\n", signum);
}

int main() {
    unsigned int duration = 5;
    unsigned int remaining_time;
    time_t start_time;

    // Register a handler for SIGINT (Ctrl+C) to demonstrate interruption capability
    signal(SIGINT, handle_signal);

    printf("Process running. Attempting to sleep for %u seconds.\n", duration);
    start_time = time(NULL);

    remaining_time = sleep(duration);

    if (remaining_time == 0) {
        printf("Sleep completed fully after %ld seconds.\n", time(NULL) - start_time);
    } else {
        // This branch executes if a signal (like SIGINT) was received during the sleep period.
        printf("Sleep interrupted! %u seconds remained.\n", remaining_time);
    }

    return 0;
}
